    /// Uses the actual shipping scene host and both native engines in one process.
    /// The Any account screen becomes enabled only after its real runtime starts.
    /// No test owner replaces the account, editor, source or engine-switch path.
    func testUnifiedEngineSwitchRetainsHeartDocumentAndColdReopen() throws {
        launch(document: .pinkha)
        openDocumentIfNeeded(.pinkha)
        let body = editableBody(startNewTrailingBlock: true)
        body.tap()
        let marker = "Unified \(UUID().uuidString.prefix(8)) עברית English"
        body.typeText(marker)
        let written = editorBody(containing: marker)
        XCTAssertTrue(written.waitForExistence(timeout: 30))
        let blockIdentifier = written.identifier
        XCTAssertTrue(blockIdentifier.hasPrefix("pinkha.stage1.body."))
        assertRuntimeDirection(on: written, document: .pinkha)
        let objectID = try XCTUnwrap(fixtureObjectIDs[.pinkha])
        let editorIdentifier = "pinkha-ui27-editor:\(fixtureSpaceID):\(objectID)"
        let editor = app.otherElements[editorIdentifier]
        XCTAssertTrue(editor.exists)
        attachScreenshot(named: "unified-heart-before-switch")

        let selector = app.buttons["pinkha.engine.selector"]
        XCTAssertTrue(selector.waitForExistence(timeout: 20), "The real combined scene host must be mounted")
        XCTAssertEqual(app.buttons.matching(identifier: "pinkha.engine.selector").count, 1)
        XCTAssertEqual(selector.value as? String, "Heart")
        selector.tap()
        let anyChoice = app.buttons["pinkha.engine.select.any"]
        XCTAssertTrue(anyChoice.waitForExistence(timeout: 10))
        anyChoice.tap()

        let nativeAccount = app.buttons["any-native-account-create"]
        XCTAssertTrue(nativeAccount.waitForExistence(timeout: 90), "Any must start through the actual embedded runtime")
        expectation(for: NSPredicate(format: "enabled == true"), evaluatedWith: nativeAccount)
        waitForExpectations(timeout: 45)
        XCTAssertEqual(selector.value as? String, "Any")
        XCTAssertFalse(written.isHittable, "The retained Heart editor must not accept input while Any is active")
        attachScreenshot(named: "unified-any-runtime-ready")

        selector.tap()
        let heartChoice = app.buttons["pinkha.engine.select.heart"]
        XCTAssertTrue(heartChoice.waitForExistence(timeout: 10))
        heartChoice.tap()
        expectation(for: NSPredicate(format: "value == %@ AND enabled == true", "Heart"), evaluatedWith: selector)
        waitForExpectations(timeout: 60)

        // Do not navigate or recreate the document here: switching must reveal
        // the same mounted Heart scene, exact original document and native block.
        XCTAssertTrue(editor.waitForExistence(timeout: 30))
        XCTAssertTrue(editor.isHittable)
        let retained = editorBody(containing: marker)
        XCTAssertTrue(retained.waitForExistence(timeout: 30))
        XCTAssertEqual(retained.identifier, blockIdentifier)
        assertRuntimeDirection(on: retained, document: .pinkha)
        attachScreenshot(named: "unified-heart-after-switch")

        launch(document: .pinkha)
        openDocumentIfNeeded(.pinkha)
        let reopened = editorBody(containing: marker)
        XCTAssertTrue(reopened.waitForExistence(timeout: 60))
        XCTAssertEqual(reopened.identifier, blockIdentifier)
        XCTAssertTrue(app.otherElements[editorIdentifier].isHittable)
        XCTAssertEqual(app.buttons["pinkha.engine.selector"].value as? String, "Heart")
        assertRuntimeDirection(on: reopened, document: .pinkha)
        attachScreenshot(named: "unified-heart-cold-reopen")
    }

    private func exerciseMultiBlockEnterLifecycle(_ kind: DocumentKind) throws {
        openDocumentIfNeeded(kind)
        var target = editableBody(startNewTrailingBlock: true)
        target.tap()

        let token = UUID().uuidString.prefix(8)
        let lines = (1...5).map { index in
            let usesHebrew = expectsRTL ? !index.isMultiple(of: 2) : index.isMultiple(of: 2)
            return usesHebrew ? "שורה \(index) בדיקה \(token)" : "Line \(index) test \(token)"
        }
        var typedBlockIDs = Set<String>()
        for (index, line) in lines.enumerated() {
            target.typeText(line)
            let typedRow = editorBody(containing: line)
            XCTAssertTrue(typedRow.waitForExistence(timeout: 20), "Entered line missing: \(line)")
            XCTAssertTrue(typedBlockIDs.insert(typedRow.identifier).inserted, "Enter reused a previously typed block")
            assertRuntimeDirection(on: typedRow, document: kind)
            if index > 0 {
                let direction = expectsRTL ? "rtl" : "ltr"
                expectation(for: NSPredicate(format: "label CONTAINS %@", "accepted-first-insertion-\(direction)"), evaluatedWith: typedRow)
                waitForExpectations(timeout: 20)
            }

            typedRow.typeText("\n")
            target = app.textViews.matching(NSPredicate(
                format: "identifier BEGINSWITH %@ AND NOT (identifier IN %@) AND label CONTAINS %@",
                "pinkha.stage1.body.",
                Array(typedBlockIDs),
                "first-responder-true"
            )).firstMatch
            XCTAssertTrue(target.waitForExistence(timeout: 20), "Enter did not focus a distinct next block")
            assertRuntimeDirection(on: target, document: kind)
            let direction = expectsRTL ? "rtl" : "ltr"
            let side = expectsRTL ? "right" : "left"
            for fragment in ["text-empty-true", "typing-direction-\(direction)", "caret-side-\(side)"] {
                expectation(for: NSPredicate(format: "label CONTAINS %@", fragment), evaluatedWith: target)
            }
            waitForExpectations(timeout: 20)
            attachScreenshot(named: "\(directionName)-\(kind.rawValue)-enter-\(typedBlockIDs.count)")
        }
        XCTAssertEqual(typedBlockIDs.count, 5)

        launch(document: kind)
        openDocumentIfNeeded(kind)
        var reopenedIDs = Set<String>()
        for line in lines {
            let row = editorBody(containing: line)
            XCTAssertTrue(row.waitForExistence(timeout: 60), "Line did not survive relaunch: \(line)")
            XCTAssertTrue(reopenedIDs.insert(row.identifier).inserted)
            assertRuntimeDirection(on: row, document: kind)
        }
        XCTAssertEqual(reopenedIDs, typedBlockIDs, "Enter-created block identities changed after relaunch")
        attachScreenshot(named: "\(directionName)-\(kind.rawValue)-multiblock-reopened")
    }

    private func editorBody(containing text: String) -> XCUIElement {
        app.textViews.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND value CONTAINS %@",
            "pinkha.stage1.body.",
            text
        )).firstMatch
    }

    private func exerciseDocument(_ kind: DocumentKind) throws {
        openDocumentIfNeeded(kind)
        var body = editableBody(startNewTrailingBlock: true)
        guard body.waitForExistence(timeout: 300) else {
            attachScreenshot(named: "FAIL-\(kind.rawValue)-editor-body-missing")
            XCTFail("Production editor body UITextView did not appear for \(kind.rawValue)")
            return
        }
        body.tap()
        let enteredText = text(for: kind)
        body.typeText(enteredText)
        body = editorBody(containing: enteredText)
        XCTAssertTrue(body.waitForExistence(timeout: 20))

        assertRuntimeDirection(on: body, document: kind)
        attachScreenshot(named: "\(directionName)-\(kind.rawValue)-entry")

        let window = app.windows.firstMatch
        XCTAssertTrue(window.exists)
        performInteractiveBack(
            in: window,
            body: body,
            startX: 0.50,
            cancelledEndX: expectsRTL ? 0.38 : 0.62,
            completedEndX: expectsRTL ? 0.05 : 0.95,
            evidencePrefix: "\(directionName)-\(kind.rawValue)-full-screen"
        )

        launch(document: kind)
        openDocumentIfNeeded(kind)
        let bodyAfterFullScreenPop = editorBody(containing: enteredText)
        XCTAssertTrue(bodyAfterFullScreenPop.waitForExistence(timeout: 60))
        assertRuntimeDirection(on: bodyAfterFullScreenPop, document: kind)

        performInteractiveBack(
            in: app.windows.firstMatch,
            body: bodyAfterFullScreenPop,
            startX: expectsRTL ? 0.995 : 0.005,
            cancelledEndX: expectsRTL ? 0.86 : 0.14,
            completedEndX: expectsRTL ? 0.18 : 0.82,
            evidencePrefix: "\(directionName)-\(kind.rawValue)-edge"
        )

        launch(document: kind)
        openDocumentIfNeeded(kind)
        let reopenedBody = editorBody(containing: enteredText)
        XCTAssertTrue(reopenedBody.waitForExistence(timeout: 60), "\(kind.rawValue) did not reopen")
        assertRuntimeDirection(on: reopenedBody, document: kind)
        XCTAssertTrue(
            String(describing: reopenedBody.value).contains(enteredText),
            "Entered text did not survive close and reopen for \(kind.rawValue)"
        )
        attachScreenshot(named: "\(directionName)-\(kind.rawValue)-reopened")
    }

    private func openDocumentIfNeeded(_ kind: DocumentKind) {
        let expectedTitle = documentTitle(for: kind)
        let titleFields = app.textViews.matching(
            NSPredicate(format: "identifier BEGINSWITH %@", "pinkha.stage1.title.")
        )
        let identity = kind == .note ? editorBody(containing: expectedTitle) : app.textViews.matching(
            NSPredicate(format: "identifier BEGINSWITH %@ AND value CONTAINS %@", "pinkha.stage1.title.", expectedTitle)
        ).firstMatch
        guard let objectID = fixtureObjectIDs[kind] else {
            XCTFail("Missing prepared native document ID")
            return
        }
        let editorMatches = app.otherElements.matching(NSPredicate(
            format: "identifier == %@", "pinkha-ui27-editor:\(fixtureSpaceID):\(objectID)"
        ))
        let editor = editorMatches.firstMatch
        if identity.exists && editor.exists && app.alerts.count == 0 {
            XCTAssertEqual(editorMatches.count, 1)
            XCTAssertTrue(editor.isHittable)
            return
        }
        var components = URLComponents()
        components.scheme = "anytype"
        components.host = "object"
        components.queryItems = [
            URLQueryItem(name: "objectId", value: objectID),
            URLQueryItem(name: "spaceId", value: fixtureSpaceID)
        ]
        guard let url = components.url else {
            XCTFail("Could not form the original native object deeplink")
            return
        }
        print("PINKHA_ACCEPTANCE_OPEN kind=\(kind.rawValue) space=\(fixtureSpaceID) object=\(objectID)")
        guard waitForPinkhaNativeNavigation(app, testCase: self, spaceID: fixtureSpaceID) else { return }
        XCUIDevice.shared.system.open(url)
        XCTAssertTrue(editor.waitForExistence(timeout: 45), "The exact native Space and document must be mounted")
        XCTAssertEqual(editorMatches.count, 1)
        XCTAssertTrue(editor.isHittable)

        if kind == .note {
            // Native Note has no title. Wait for the previous Page to leave before seeding
            // the Note's first body through real input, never into the previous document.
            XCTAssertTrue(titleFields.firstMatch.waitForNonExistence(timeout: 60))
            let body = editableBody()
            if !identity.exists {
                body.tap()
                body.typeText(expectedTitle + "\n")
            }
        }
        XCTAssertTrue(identity.waitForExistence(timeout: 60), "Prepared native \(kind.rawValue) fixture did not open")
    }

    private func documentTitle(for kind: DocumentKind) -> String {
        switch kind {
        case .pinkha:
            return "בדיקת RTL Stage 1"
        case .note:
            return "RTL Acceptance Ordinary Note"
        case .page:
            return "RTL Acceptance Ordinary Page"
        }
    }

    private func assertRuntimeDirection(
        on body: XCUIElement,
        document kind: DocumentKind
    ) {
        let direction = expectsRTL ? "rtl" : "ltr"
        let alignment = expectsRTL ? "right" : "left"
        let requiredFragments = [
            "document-\(kind.rawValue)",
            "app-language-\(appLanguage)",
            "device-language-requested-\(deviceLanguage)",
            "swiftui-\(direction)",
            "navigation-\(direction)",
            "uikit-\(direction)",
            "alignment-\(alignment)"
        ]
        let predicates = requiredFragments.map {
            NSPredicate(format: "label CONTAINS %@", $0)
        }
        expectation(
            for: NSCompoundPredicate(andPredicateWithSubpredicates: predicates),
            evaluatedWith: body
        )
        waitForExpectations(timeout: 20)
    }

    private func launch(document kind: DocumentKind) {
        if app.state != .notRunning {
            app.terminate()
        }
        app.launchEnvironment["PINKHA_ACCEPTANCE_DOCUMENT_KIND"] = kind.rawValue
        app.launch()
    }

    private func performInteractiveBack(
        in window: XCUIElement,
        body: XCUIElement,
        startX: CGFloat,
        cancelledEndX: CGFloat,
        completedEndX: CGFloat,
        evidencePrefix: String
    ) {
        let start = window.coordinate(withNormalizedOffset: CGVector(dx: startX, dy: 0.52))
        let cancelledEnd = window.coordinate(withNormalizedOffset: CGVector(dx: cancelledEndX, dy: 0.52))
        start.press(
            forDuration: 0.08,
            thenDragTo: cancelledEnd,
            withVelocity: .slow,
            thenHoldForDuration: 0.5
        )
        XCTAssertTrue(body.waitForExistence(timeout: 5), "A short back swipe should cancel and keep the editor")
        attachScreenshot(named: "\(evidencePrefix)-cancelled")

        let completedEnd = window.coordinate(withNormalizedOffset: CGVector(dx: completedEndX, dy: 0.52))
        start.press(
            forDuration: 0.08,
            thenDragTo: completedEnd,
            withVelocity: .slow,
            thenHoldForDuration: 0.05
        )
        XCTAssertTrue(body.waitForNonExistence(timeout: 12), "A completed interactive back swipe did not pop")
        attachScreenshot(named: "\(evidencePrefix)-completed")
    }

    private func editorBody() -> XCUIElement {
        let bodies = app.textViews.matching(
            NSPredicate(format: "identifier BEGINSWITH %@", "pinkha.stage1.body.")
        )
        // Keep the Note's stable first-line identity intact while editing later content.
        return bodies.element(boundBy: max(0, bodies.count - 1))
    }

    private func editableBody(startNewTrailingBlock: Bool = false) -> XCUIElement {
        let body = editorBody()
        if !startNewTrailingBlock, body.waitForExistence(timeout: 3) { return body }

        // A newly opened native document can contain metadata without a body row. The
        // original editor creates its virtual trailing row only after a tap below content.
        // Exercise that user path; never create a persisted fixture block or change focus.
        let editor = app.collectionViews.containing(.button, identifier: "torah-document-sources-add").firstMatch
        XCTAssertTrue(editor.waitForExistence(timeout: 20))
        let contentBottom = editor.cells.allElementsBoundByIndex.map { $0.frame.maxY }.max() ?? editor.frame.minY
        let keyboard = app.keyboards.firstMatch
        let visibleBottom = keyboard.exists ? min(editor.frame.maxY, keyboard.frame.minY) : editor.frame.maxY
        XCTAssertGreaterThan(visibleBottom - contentBottom, 24, "A safe native empty area is required before tapping")
        let y = contentBottom + (visibleBottom - contentBottom) * 0.5
        editor.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(
            dx: editor.frame.width * 0.5, dy: y - editor.frame.minY
        )).tap()
        let created = app.textViews.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND label CONTAINS %@ AND label CONTAINS %@",
            "pinkha.stage1.body.", "first-responder-true", "text-empty-true"
        )).firstMatch
        XCTAssertTrue(created.waitForExistence(timeout: 20), "Native empty-area tap did not expose a trailing editor row")
        return created
    }

    private func text(for kind: DocumentKind) -> String {
        if expectsRTL {
            return "טקסט \(kind.rawValue) בעברית"
        }
        return "English \(kind.rawValue) acceptance text"
    }

    private var directionName: String { expectsRTL ? "RTL" : "LTR" }

    private func attachScreenshot(named name: String) {
        let attachment = XCTAttachment(screenshot: app.screenshot())
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}

/// Test-only continuation of the exact original middleware warning. The legacy
/// fixtures have no native source/run echo: this envelope records the controller's
/// read of their unchanged bytes after the original native preparation passed on
/// its newly created simulator. It is not a native authentication receipt.
@MainActor
enum PinkhaDisposableStartupWarning {
    private struct Binding: Decodable {
        let schema: String
        let provenance: String
        let lane: String
        let sourceSHA: String
        let runID: String
        let runAttempt: String
        let token: String
        let simulatorUDID: String
        let admissionSHA256: String
        let preparationReceiptSHA256: String
        let preparationInvocationSHA256: String
        let canonicalPreparationConsoleSHA256: String
        let ownedSimulatorReceiptSHA256: String
        let preparationIdentifier: String
        let fixtureFilename: String
        let fixtureSHA256: String
        let fixtureBase64: String
        let uiEnvironment: [String: String]
    }

    static var navigationPredicate: NSPredicate {
        NSPredicate(
            format: "identifier == %@ OR label == %@ OR identifier == %@ OR label == %@ OR (elementType == %d AND (label == %@ OR label == %@))",
            "SpaceHub", "SpaceHub", "NewSpaceButton", "NewSpaceButton",
            XCUIElement.ElementType.button.rawValue, "More", "x24/More"
        )
    }

    static func waitForNavigation(
        _ app: XCUIApplication, testCase: XCTestCase, spaceID: String, allowedLanes: Set<String>
    ) throws {
        let deadline = ProcessInfo.processInfo.systemUptime + 120
        do {
            let binding = try validateBinding(spaceID: spaceID, allowedLanes: allowedLanes)
            let words = try warningStrings(language: try XCTUnwrap(binding.uiEnvironment["PINKHA_UI27_APP_LANGUAGE"]))
            let warningPredicate = NSPredicate(format: "elementType == %d AND label == %@",
                XCUIElement.ElementType.alert.rawValue, words.title)
            let ready = app.descendants(matching: .any).matching(navigationPredicate).firstMatch
            let startup = app.descendants(matching: .any).matching(NSCompoundPredicate(
                orPredicateWithSubpredicates: [navigationPredicate, warningPredicate])).firstMatch
            try require(startup.waitForExistence(timeout: remaining(deadline)),
                        "Restored native navigation did not become ready")
            let warnings = app.alerts.matching(NSPredicate(format: "label == %@", words.title))
            if warnings.firstMatch.exists {
                let warning = warnings.firstMatch
                try require(warnings.count == 1 && app.alerts.count == 1,
                            "Original startup warning is not unique")
                let messages = warning.staticTexts.matching(NSPredicate(format: "label == %@", words.message))
                let proceed = warning.buttons.matching(NSPredicate(format: "label == %@", words.proceed))
                let logout = warning.buttons.matching(NSPredicate(format: "label == %@", words.logout))
                try require(messages.count == 1 && messages.firstMatch.exists,
                            "Original startup warning message differs")
                try require(warning.buttons.count == 2 && proceed.count == 1 && logout.count == 1,
                            "Original startup warning actions differ")
                let button = proceed.firstMatch
                try require(button.exists && button.isEnabled && button.isHittable,
                            "Original Continue action is not hittable")
                attach(app, testCase: testCase, name: "controller-disposable-startup-warning")
                let receipt = XCTAttachment(string:
                    "provenance=\(binding.provenance); lane=\(binding.lane); sourceSHA=\(binding.sourceSHA); " +
                    "runID=\(binding.runID); runAttempt=\(binding.runAttempt); simulatorUDID=\(binding.simulatorUDID); " +
                    "fixtureSHA256=\(binding.fixtureSHA256); preparationReceiptSHA256=\(binding.preparationReceiptSHA256); " +
                    "canonicalPreparationConsoleSHA256=\(binding.canonicalPreparationConsoleSHA256)")
                receipt.name = "controller-disposable-startup-binding"
                receipt.lifetime = .keepAlways
                testCase.add(receipt)
                _ = try remaining(deadline)
                button.tap()
                try require(warning.waitForNonExistence(timeout: remaining(deadline)),
                            "Original startup warning remained")
            }
            try require(ready.waitForExistence(timeout: remaining(deadline)),
                        "Restored native navigation did not become ready")
            try require(app.alerts.count == 0, "An alert still obscures the restored native navigation")
        } catch {
            attach(app, testCase: testCase, name: "controller-disposable-startup-failure")
            throw error
        }
    }

    private static func validateBinding(spaceID: String, allowedLanes: Set<String>) throws -> Binding {
        let environment = ProcessInfo.processInfo.environment
        let json = try XCTUnwrap(environment["PINKHA_UI27_STARTUP_BINDING_JSON"],
                                "Missing controller-observed disposable fixture binding")
        try require(json.utf8.count <= 262_144, "Startup fixture binding is oversized")
        let binding = try JSONDecoder().decode(Binding.self, from: Data(json.utf8))
        try require(binding.schema == "pinkha-controller-observed-native-ui-fixture-v1"
                    && binding.provenance == "CONTROLLER_OWNED_SIMULATOR_AFTER_ORIGINAL_NATIVE_PREPARATION"
                    && allowedLanes.contains(binding.lane), "Startup fixture provenance or lane differs")
        let expected: [String: String] = [
            "SOURCE_SHA": binding.sourceSHA, "RUN_ID": binding.runID, "RUN_ATTEMPT": binding.runAttempt,
            "TOKEN": binding.token, "SIMULATOR_UDID": binding.simulatorUDID, "LANE": binding.lane,
            "ADMISSION_SHA256": binding.admissionSHA256, "PREPARATION_SHA256": binding.preparationReceiptSHA256,
            "INVOCATION_SHA256": binding.preparationInvocationSHA256,
            "CANONICAL_CONSOLE_SHA256": binding.canonicalPreparationConsoleSHA256,
            "OWNED_SIMULATOR_SHA256": binding.ownedSimulatorReceiptSHA256, "FIXTURE_SHA256": binding.fixtureSHA256
        ]
        try require(expected.allSatisfy { environment["PINKHA_UI27_STARTUP_" + $0.key] == $0.value },
                    "Startup binding differs from the selected controller environment")
        try require(matches(binding.sourceSHA, "[0-9a-f]{40}")
                    && matches(binding.token, "[0-9a-f]{32}")
                    && matches(binding.runID, "[0-9]+") && matches(binding.runAttempt, "[0-9]+")
                    && UUID(uuidString: binding.simulatorUDID) != nil,
                    "Startup source/run/simulator identity is invalid")
        try require([binding.admissionSHA256, binding.preparationReceiptSHA256, binding.preparationInvocationSHA256,
                     binding.ownedSimulatorReceiptSHA256, binding.fixtureSHA256].allSatisfy { matches($0, "[0-9a-f]{64}") },
                    "Startup evidence hashes are invalid")
        let expectedPreparation: (String, String)
        switch binding.lane {
        case "inspector", "inspector-search", "quote-drop":
            expectedPreparation = ("SimulatorAcceptancePreparationTests/prepareRealUIFixture", "pinkha-simulator-ui27-fixture.json")
        case "properties", "properties-set":
            expectedPreparation = ("TorahNativeDerivedProductIntegrationTests/originalProductPipeline", "pinkha-native-derived-ui-fixture.json")
        case "canonical-properties", "editor":
            expectedPreparation = ("PinkhaStage1AcceptancePreparationTests/prepareRealApplicationState", "pinkha-stage1-acceptance-state.json")
        default:
            throw failure("Unsupported startup fixture lane")
        }
        try require(binding.preparationIdentifier == expectedPreparation.0 && binding.fixtureFilename == expectedPreparation.1,
                    "Startup native fixture or preparation identity differs")
        let data = try XCTUnwrap(Data(base64Encoded: binding.fixtureBase64), "Native fixture bytes are missing")
        try require(!data.isEmpty && data.count <= 65_536, "Native fixture bytes are empty or oversized")
        let digest = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
        try require(digest == binding.fixtureSHA256, "Original native fixture bytes changed")
        let native = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        try require(!spaceID.isEmpty && native["spaceId"] as? String == spaceID,
                    "Startup fixture belongs to another Space")
        try require(!binding.uiEnvironment.isEmpty && binding.uiEnvironment.allSatisfy {
            !$0.key.hasPrefix("PINKHA_UI27_STARTUP_") && environment[$0.key] == $0.value
        }, "Original fixture UI environment changed")
        let language = binding.uiEnvironment["PINKHA_UI27_APP_LANGUAGE"]
        try require(binding.uiEnvironment["PINKHA_NATIVE_UI_DISPOSABLE"] == "1"
                    && (language == "en" || (binding.lane == "editor" && language == "he"))
                    && binding.uiEnvironment["PINKHA_UI27_SELECTION_SCOPE"] == "WAVE15_ACCEPTANCE",
                    "Original disposable UI language scope is missing")
        if binding.lane == "canonical-properties" {
            try require(matches(binding.canonicalPreparationConsoleSHA256, "[0-9a-f]{64}"),
                        "Original canonical preparation console evidence is missing")
            try require(binding.uiEnvironment["PINKHA_PROPERTIES_SPACE_ID"] == spaceID
                        && binding.uiEnvironment["PINKHA_PROPERTIES_ISOLATED_SPACE_CONFIRMED"] == "1",
                        "Original canonical property preparation differs")
            let ids = try ["CHIDDUSH", "ARTICLE", "RESEARCH"].map {
                try XCTUnwrap(binding.uiEnvironment["PINKHA_PROPERTIES_" + $0 + "_ID"])
            }
            try require(ids.allSatisfy { !$0.isEmpty } && Set(ids).count == 3,
                        "Canonical writing documents are not distinct")
        } else {
            try require(binding.canonicalPreparationConsoleSHA256.isEmpty,
                        "Unexpected canonical preparation console in another lane")
            if binding.lane == "editor" {
                try require(binding.uiEnvironment["PINKHA_ACCEPTANCE_SPACE_ID"] == spaceID,
                            "Editor fixture Space differs")
                let fields = [("pinkhaObjectId", "PINKHA"), ("noteObjectId", "NOTE"), ("pageObjectId", "PAGE")]
                let ids = try fields.map { field, suffix in
                    let id = try XCTUnwrap(native[field] as? String)
                    try require(!id.isEmpty && binding.uiEnvironment["PINKHA_ACCEPTANCE_" + suffix + "_ID"] == id,
                                "Editor document differs from the original native fixture")
                    return id
                }
                try require(Set(ids).count == 3, "Editor requires three distinct original documents")
                try require(binding.uiEnvironment["PINKHA_ACCEPTANCE_DIRECTION"] == (language == "he" ? "rtl" : "ltr")
                            && binding.uiEnvironment["PINKHA_ACCEPTANCE_DEVICE_LANGUAGE"] == (language == "he" ? "en" : "he"),
                            "Editor app direction and opposite device language differ")
            } else {
                let uiJSON = try XCTUnwrap(binding.uiEnvironment["PINKHA_NATIVE_UI_FIXTURE_JSON"])
                let uiFixture = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(uiJSON.utf8)) as? [String: Any])
                try require(NSDictionary(dictionary: native).isEqual(to: uiFixture),
                            "UI fixture IDs differ from the original native fixture")
            }
        }
        if binding.lane == "inspector" || binding.lane == "inspector-search" {
            let pid = binding.uiEnvironment["PINKHA_UI27_EXPECTED_APP_PID"].flatMap(Int.init)
            try require((pid ?? 0) > 0, "Inspector requires the controller's verified prelaunch PID")
        }
        return binding
    }

    // Exact Auth.xcstrings values, selected by the bound App language; never
    // accept either language opportunistically or dismiss a different alert.
    private static func warningStrings(language: String) throws -> (title: String, message: String, proceed: String, logout: String) {
        switch language {
        case "en":
            return ("Warning", "You launch app with a unstable middleware. Don't use your production vault. Your vault may be broken.",
                    "Continue with current vault", "Logout from current vault")
        case "he":
            return ("אזהרה", "הפעלת את האפליקציה עם תווכה (middleware) לא יציבה. אל תשתמש בכספת הייצור שלך. הכספת עלולה להיפגם.",
                    "המשך עם הכספת הנוכחית", "התנתק מהכספת הנוכחית")
        default:
            throw failure("Unsupported original startup warning language")
        }
    }

    private static func matches(_ value: String, _ pattern: String) -> Bool {
        value.range(of: "\\A(?:" + pattern + ")\\z", options: .regularExpression) != nil
    }

    private static func remaining(_ deadline: TimeInterval) throws -> TimeInterval {
        let value = deadline - ProcessInfo.processInfo.systemUptime
        try require(value > 0, "Original native navigation deadline expired")
        return value
    }

    private static func require(_ condition: Bool, _ message: String) throws {
        if !condition { throw failure(message) }
    }

    private static func failure(_ message: String) -> NSError {
        NSError(domain: "PinkhaControllerDisposableStartup", code: 1,
                userInfo: [NSLocalizedDescriptionKey: message])
    }

    private static func attach(_ app: XCUIApplication, testCase: XCTestCase, name: String) {
        let hierarchy = XCTAttachment(string: app.debugDescription)
        hierarchy.name = name + "-accessibility"
        hierarchy.lifetime = .keepAlways
        testCase.add(hierarchy)
        let screenshot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        screenshot.name = name
        screenshot.lifetime = .keepAlways
        testCase.add(screenshot)
    }
}

// Additive real-input coverage. The four original editor methods, native
// preparation, fixture binding and startup warning implementation remain intact.
extension PinkhaStage1AcceptanceUITests {
    func testMiddleSplitMergeUndoRedoAndColdReopen() throws {
        executionTimeAllowance = 1_200
        defer { attachMutationState("middle-split-merge-final") }
        XCTAssertNotEqual(appLanguage, deviceLanguage)

        for kind in DocumentKind.allCases {
            launch(document: kind)
            openDocumentIfNeeded(kind)
            let token = String(UUID().uuidString.replacingOccurrences(of: "-", with: "").prefix(8))
            let guardText = "Guard_" + token
            let (guardID, input) = try createMutationTarget(guardText: guardText)
            // ASCII makes physical left-arrow traversal unambiguous within the
            // selected run, including when the app and OS directions differ.
            let prefix = "Left_" + token, suffix = "Right_" + token
            let originalText = prefix + suffix
            input.typeText(originalText)
            let original = try mutationBody(text: originalText)
            let originalID = original.identifier
            try mutationRequire(originalID != guardID, "The typed target reused the guard block identity")
            let joined = [guardID: guardText, originalID: originalText]
            try waitForMutationSnapshot(joined, token: token)
            try requireMutationFocus(original, tap: false)

            for _ in 0..<suffix.utf16.count {
                original.typeKey(.leftArrow, modifierFlags: [])
            }
            // No text view or app-process selection setter is used. The exact
            // two resulting strings below prove where the real Return split.
            original.typeText("\n")
            let second = try mutationBody(text: suffix)
            let secondID = second.identifier
            try mutationRequire(secondID != originalID && secondID != guardID,
                                "Split did not publish a distinct second block identity")
            let split = [guardID: guardText, originalID: prefix, secondID: suffix]
            try waitForMutationSnapshot(split, token: token)
            try requireMutationFocus(second, tap: false)
            try recordMutation("split", kind: kind, token: token, expected: split,
                               rangeEvidence: "INFERRED_FROM_EXACT_PREFIX_SUFFIX_AFTER_REAL_RETURN")

            try performMutationHistory("editor-undo", kind: kind)
            try waitForMutationSnapshot(joined, token: token, absent: [secondID])
            try recordMutation("split-undo", kind: kind, token: token, expected: joined)
            try performMutationHistory("editor-redo", kind: kind)
            try waitForMutationSnapshot(split, token: token)
            try recordMutation("split-redo", kind: kind, token: token, expected: split)

            let right = mutationBody(identifier: secondID)
            try requireMutationFocus(right, tap: true)
            right.typeKey("a", modifierFlags: .command)
            right.typeKey(.leftArrow, modifierFlags: [])
            right.typeText(XCUIKeyboardKey.delete.rawValue)
            try waitForMutationSnapshot(joined, token: token, absent: [secondID])
            try requireMutationFocus(mutationBody(identifier: originalID), tap: false)
            try recordMutation("merge", kind: kind, token: token, expected: joined,
                               rangeEvidence: "INFERRED_FROM_EXACT_MERGE_AFTER_REAL_COMMAND_A_LEFT_BACKSPACE")

            try performMutationHistory("editor-undo", kind: kind)
            try waitForMutationSnapshot(split, token: token)
            try recordMutation("merge-undo", kind: kind, token: token, expected: split)
            try performMutationHistory("editor-redo", kind: kind)
            try waitForMutationSnapshot(joined, token: token, absent: [secondID])
            try recordMutation("merge-redo", kind: kind, token: token, expected: joined)
            try coldReadMutation(kind: kind, token: token, expected: joined,
                                 absent: [secondID], phase: "split-merge-cold-readback")
        }
    }

    func testPartialRangeReplacementUndoRedoAndColdReopen() throws {
        executionTimeAllowance = 1_200
        defer { attachMutationState("partial-replacement-final") }
        XCTAssertNotEqual(appLanguage, deviceLanguage)

        for kind in DocumentKind.allCases {
            launch(document: kind)
            openDocumentIfNeeded(kind)
            let token = String(UUID().uuidString.replacingOccurrences(of: "-", with: "").prefix(8))
            let guardText = "Guard_" + token
            let (guardID, input) = try createMutationTarget(guardText: guardText)
            let prefix = "Left_" + token, selected = "MIDDLE", suffix = "Right_" + token
            let originalText = prefix + selected + suffix
            input.typeText(originalText)
            let original = try mutationBody(text: originalText)
            let originalID = original.identifier
            try mutationRequire(originalID != guardID, "The typed target reused the guard block identity")
            let before = [guardID: guardText, originalID: originalText]
            try waitForMutationSnapshot(before, token: token)
            try requireMutationFocus(original, tap: false)

            for _ in 0..<suffix.utf16.count {
                original.typeKey(.leftArrow, modifierFlags: [])
            }
            for _ in 0..<selected.utf16.count {
                original.typeKey(.leftArrow, modifierFlags: .shift)
            }
            attachMutationState(kind.rawValue + "-real-shift-selection")
            // One ordinary replacement key keeps this edit distinct from a
            // sequence of typing transactions. Prefix and suffix must survive.
            original.typeText("Z")
            let editedText = prefix + "Z" + suffix
            let edited = [guardID: guardText, originalID: editedText]
            try waitForMutationSnapshot(edited, token: token)
            try recordMutation("partial-replacement", kind: kind, token: token, expected: edited,
                               rangeEvidence: "INFERRED_FROM_EXACT_UNCHANGED_PREFIX_SUFFIX_AFTER_REAL_SHIFT_RANGE")

            try performMutationHistory("editor-undo", kind: kind)
            try waitForMutationSnapshot(before, token: token)
            try recordMutation("replacement-undo", kind: kind, token: token, expected: before)
            try performMutationHistory("editor-redo", kind: kind)
            try waitForMutationSnapshot(edited, token: token)
            try requireMutationFocus(mutationBody(identifier: originalID), tap: true)
            try recordMutation("replacement-redo", kind: kind, token: token, expected: edited)
            try coldReadMutation(kind: kind, token: token, expected: edited,
                                 phase: "replacement-cold-readback")
        }
    }

    private func createMutationTarget(guardText: String) throws -> (String, XCUIElement) {
        let first = editableBody(startNewTrailingBlock: true)
        first.tap()
        first.typeText(guardText)
        let guardRow = try mutationBody(text: guardText)
        let guardID = guardRow.identifier
        guardRow.typeText("\n")
        let following = app.textViews.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND identifier != %@ AND label CONTAINS %@ AND value == %@",
            "pinkha.stage1.body.", guardID, "first-responder-true", ""
        )).firstMatch
        try mutationRequire(following.waitForExistence(timeout: 30), "Return did not expose a distinct empty target")
        try requireMutationFocus(following, tap: false)
        return (guardID, following)
    }

    private func mutationBody(identifier: String) -> XCUIElement {
        app.textViews.matching(NSPredicate(format: "identifier == %@", identifier)).firstMatch
    }

    private func mutationBody(text: String) throws -> XCUIElement {
        let matches = app.textViews.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND value == %@", "pinkha.stage1.body.", text
        ))
        try mutationRequire(matches.firstMatch.waitForExistence(timeout: 30), "Exact edited text did not render")
        try mutationRequire(matches.count == 1 && !matches.firstMatch.identifier.isEmpty,
                            "The exact text must belong to one native block")
        return matches.firstMatch
    }

    private func waitForMutationSnapshot(_ expected: [String: String], token: String,
                                         absent: [String] = []) throws {
        let rows = app.textViews.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND value CONTAINS %@", "pinkha.stage1.body.", token
        ))
        let settled = NSPredicate { _, _ in
            let current = rows.allElementsBoundByIndex
            return current.count == expected.count
                && Set(current.map(\.identifier)) == Set(expected.keys)
                && current.allSatisfy { ($0.value as? String) == expected[$0.identifier] }
                && absent.allSatisfy { !self.mutationBody(identifier: $0).exists }
        }
        let result = XCTWaiter.wait(for: [XCTNSPredicateExpectation(predicate: settled, object: app)], timeout: 45)
        try mutationRequire(result == .completed,
                            "Mutation did not settle to the exact block IDs/text/count before the next history action")
        // This is an observed UI state, not a native save acknowledgement.
        // Storage acceptance is established separately by coldReadMutation.
    }

    private func requireMutationFocus(_ row: XCUIElement, tap: Bool) throws {
        try mutationRequire(row.exists && row.isHittable, "The target block is not reachable")
        if tap { row.tap() }
        let focused = XCTNSPredicateExpectation(predicate: NSPredicate(
            format: "label CONTAINS %@", "first-responder-true"), object: row)
        try mutationRequire(XCTWaiter.wait(for: [focused], timeout: 20) == .completed,
                            "The real target input did not acquire focus")
        try mutationRequire(app.keyboards.firstMatch.waitForExistence(timeout: 20),
                            "The real system keyboard did not appear")
    }

    private func performMutationHistory(_ identifier: String, kind: DocumentKind) throws {
        try mutationRequire(identifier == "editor-undo" || identifier == "editor-redo", "Unsupported history action")
        let more = app.buttons.matching(NSPredicate(format: "label == %@ OR label == %@", "More", "x24/More")).firstMatch
        try mutationRequire(more.waitForExistence(timeout: 20) && more.isHittable, "Native document actions are unavailable")
        more.tap()
        let menu = app.buttons["editor-object-action-undoredo"]
        if !menu.waitForExistence(timeout: 5) {
            let nested = app.buttons.matching(NSPredicate(format: "label == %@", "More"))
                .allElementsBoundByIndex.filter(\.isHittable)
            try mutationRequire(nested.count == 1, "The original nested history menu is not unique")
            nested[0].tap()
        }
        try mutationRequire(menu.waitForExistence(timeout: 20) && menu.isHittable, "Native Undo/Redo menu is unavailable")
        menu.tap()
        let action = app.buttons[identifier]
        try mutationRequire(action.waitForExistence(timeout: 20) && action.isEnabled && action.isHittable,
                            "The requested real history action is unavailable")
        let actionTop = action.frame.minY
        action.tap()
        if action.exists {
            let window = app.windows.firstMatch
            let top = window.frame.minY + 80
            try mutationRequire(actionTop > top + 40, "No safe native history-sheet dismissal background")
            window.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(
                dx: window.frame.width * 0.5, dy: (top + actionTop) * 0.5 - window.frame.minY
            )).tap()
        }
        try mutationRequire(action.waitForNonExistence(timeout: 20), "Native history sheet did not dismiss")
        let objectID = try XCTUnwrap(fixtureObjectIDs[kind])
        let editor = app.otherElements["pinkha-ui27-editor:\(fixtureSpaceID):\(objectID)"]
        try mutationRequire(editor.exists && editor.isHittable && app.alerts.count == 0,
                            "History returned to a different or obscured document")
    }

    private func coldReadMutation(kind: DocumentKind, token: String, expected: [String: String],
                                  absent: [String] = [], phase: String) throws {
        let beforePID = try mutationProcessID()
        app.terminate()
        try mutationRequire(app.wait(for: .notRunning, timeout: 20), "The old editor process did not terminate")
        launch(document: kind)
        openDocumentIfNeeded(kind)
        let afterPID = try mutationProcessID()
        try mutationRequire(afterPID != beforePID, "Cold readback reused the previous app process")
        try waitForMutationSnapshot(expected, token: token, absent: absent)
        try recordMutation(phase, kind: kind, token: token, expected: expected,
                           persistedReadback: true, previousPID: beforePID)
    }

    private func mutationProcessID() throws -> Int {
        let text = app.debugDescription
        let expression = try NSRegularExpression(pattern: "\\A\\s*(?:Attributes:\\s*)?Application,\\s*0x[0-9a-fA-F]+,\\s*pid:\\s*([0-9]+)")
        let range = NSRange(text.startIndex..., in: text)
        let match = try XCTUnwrap(expression.firstMatch(in: text, range: range), "Actual App PID is absent")
        let digits = try XCTUnwrap(Range(match.range(at: 1), in: text))
        let pid = try XCTUnwrap(Int(text[digits]))
        try mutationRequire(pid > 0, "Actual App PID is invalid")
        return pid
    }

    private func recordMutation(_ phase: String, kind: DocumentKind, token: String,
                                expected: [String: String],
                                rangeEvidence: String = "NO_PRE_EDIT_RANGE_CLAIM",
                                persistedReadback: Bool = false, previousPID: Int? = nil) throws {
        let env = ProcessInfo.processInfo.environment
        let binding = try XCTUnwrap(env["PINKHA_UI27_STARTUP_BINDING_JSON"])
        let objectID = try XCTUnwrap(fixtureObjectIDs[kind])
        let editor = app.otherElements.matching(NSPredicate(
            format: "identifier == %@", "pinkha-ui27-editor:\(fixtureSpaceID):\(objectID)"))
        try mutationRequire(editor.count == 1 && editor.firstMatch.isHittable && app.alerts.count == 0,
                            "Observation does not belong to the current unobscured fixture document")
        let actualRows = app.textViews.matching(NSPredicate(
            format: "identifier BEGINSWITH %@ AND value CONTAINS %@", "pinkha.stage1.body.", token
        )).allElementsBoundByIndex
        var observed: [String: String] = [:]
        for row in actualRows {
            let text = try XCTUnwrap(row.value as? String, "Observed block text is missing")
            try mutationRequire(observed[row.identifier] == nil, "Duplicate observed block identity")
            observed[row.identifier] = text
        }
        try mutationRequire(observed == expected, "Observed block state changed before evidence capture")
        var value: [String: Any] = [
            "schema": "pinkha-heart-editor-mutation-observation-v1", "phase": phase,
            "documentKind": kind.rawValue, "spaceID": fixtureSpaceID, "objectID": objectID,
            "token": token, "appLanguage": appLanguage, "requestedDeviceLanguage": deviceLanguage,
            "appPID": try mutationProcessID(), "expectedBlocks": expected, "observedBlocks": observed,
            "startupBindingSHA256": SHA256.hash(data: Data(binding.utf8)).map { String(format: "%02x", $0) }.joined(),
            "rangeEvidence": rangeEvidence, "directNativeRangeObservation": false,
            "programmaticSelectionChanges": 0, "persistedColdReadback": persistedReadback,
            "saveEvidence": persistedReadback ? "DISTINCT_COLD_PROCESS_EXACT_ID_AND_TEXT_READBACK" : "UI_STATE_ONLY"
        ]
        if let previousPID { value["previousPID"] = previousPID }
        let attachment = XCTAttachment(data: try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys]),
                                       uniformTypeIdentifier: "public.json")
        attachment.name = "editor-mutation-" + kind.rawValue + "-" + phase
        attachment.lifetime = .keepAlways
        add(attachment)
        attachMutationState(kind.rawValue + "-" + phase)
    }

    private func attachMutationState(_ phase: String) {
        let hierarchy = XCTAttachment(string: app.debugDescription)
        hierarchy.name = "editor-mutation-" + phase + "-ax"
        hierarchy.lifetime = .keepAlways
        add(hierarchy)
        if app.state == .runningForeground {
            attachScreenshot(named: "editor-mutation-" + phase + "-visual")
        }
    }

    private func mutationRequire(_ value: @autoclosure () -> Bool, _ reason: String) throws {
        guard value() else {
            XCTFail(reason)
            throw NSError(domain: "PinkhaEditorMutationAcceptance", code: 1,
                          userInfo: [NSLocalizedDescriptionKey: reason])
        }
    }
}

